@startuml

class Customer {
  + address : string
  + vat_number : string
}

class Address {
  + address : string
}

class Product {
  + name : string
  + stock_level : int
}

class Order {
  + order_date : date
  + payment_date : date
  + delivery_date : date
}

class OrderLine {
  + quantity : int
}

class Invoice {
  + invoice_date : date
}

class Shipment {
  + status : ShipmentStatus
}

enum ShipmentStatus {
  Packed
  Shipped
  Received
}

class Warehouse {
  + address : string
}

class Supermarket {
  + head_office_address : Address
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Customer "1" -- "*" Supermarket : is
Supermarket "1" -- "*" Warehouse : has
Supermarket "1" -- "*" Address : delivers_to
Order "1" *-- "1..*" OrderLine : contains
Order "1" -- "0..1" Invoice : billed_by
Order "1" -- "*" Shipment : split_into
OrderLine "1" -- "*" Shipment : part_of
Shipment "*" -- "1" Warehouse : departs_from

@enduml

